using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tool implementations ----------------------------------------------------

var notebook = new Notebook();
var webSearcher = new WebSearcher();

var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearcher.SearchWeb),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// --- Build the agent ---------------------------------------------------------

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic:
        1. Search the web for relevant information using the search_web tool (make 2-3 searches with different queries).
        2. Save important findings as notes using the add_note tool.
        3. After gathering enough information, retrieve all notes with the get_notes tool.
        4. Provide a concise, well-structured summary of your research findings.
        Always cite the sources (titles and URLs) you found.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// --- Run the agent -----------------------------------------------------------

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║        Research Agent (GPT-4o)       ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

string topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptUser();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var session = await agent.CreateSessionAsync();

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

await foreach (var update in agent.RunStreamingAsync(topic, session, runOptions))
{
    if (update.Text is { Length: > 0 } text)
    {
        Console.Write(text);
    }
}

Console.WriteLine("\n\n--- Research complete ---");

// --- Helpers -----------------------------------------------------------------

static string PromptUser()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? "Recent advances in quantum computing 2025"
        : input;
}

// --- Tool classes ------------------------------------------------------------

/// <summary>Searches the web using the Brave Search API or falls back to a simulated search.</summary>
sealed class WebSearcher
{
    private static readonly HttpClient Http = new();

    [Description("Search the web for information on a query. Returns a list of results with titles, URLs, and snippets.")]
    public async Task<IReadOnlyList<SearchResult>> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        var braveApiKey = Environment.GetEnvironmentVariable("BRAVE_API_KEY");
        if (!string.IsNullOrEmpty(braveApiKey))
        {
            return await SearchWithBrave(query, braveApiKey);
        }

        // Fallback: simulated results when no search API key is configured
        return SimulateSearch(query);
    }

    private static async Task<IReadOnlyList<SearchResult>> SearchWithBrave(string query, string apiKey)
    {
        var request = new HttpRequestMessage(HttpMethod.Get,
            $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count=5");
        request.Headers.Add("X-Subscription-Token", apiKey);
        request.Headers.Add("Accept", "application/json");

        var response = await Http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.CreateAsync(await response.Content.ReadAsStreamAsync());

        var results = new List<SearchResult>();
        if (doc.RootElement.TryGetProperty("web", out var web) &&
            web.TryGetProperty("results", out var webResults))
        {
            foreach (var r in webResults.EnumerateArray().Take(5))
            {
                results.Add(new SearchResult(
                    r.GetProperty("title").GetString() ?? "",
                    r.GetProperty("url").GetString() ?? "",
                    r.GetProperty("description").GetString() ?? ""));
            }
        }

        return results;
    }

    private static IReadOnlyList<SearchResult> SimulateSearch(string query)
    {
        Console.WriteLine("  ⚠️  No BRAVE_API_KEY set — using simulated results.");
        var slug = query.Replace(' ', '-').ToLowerInvariant();
        return
        [
            new($"Overview: {query}", $"https://example.com/{slug}/overview",
                $"A comprehensive overview of {query}, covering recent developments and key concepts."),
            new($"Latest Research on {query}", $"https://example.com/{slug}/research",
                $"Academic and industry research highlights related to {query}."),
            new($"{query} - Wikipedia", $"https://en.wikipedia.org/wiki/{slug}",
                $"Wikipedia article providing background information on {query}."),
        ];
    }
}

record SearchResult(string Title, string Url, string Snippet);

/// <summary>A simple in-memory notebook for the agent to record findings.</summary>
sealed class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Save a research note. Use this to record important findings from search results.")]
    public string AddNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count} saved");
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieve all saved research notes.")]
    public IReadOnlyList<string> GetNotes()
    {
        Console.WriteLine($"  📓 Returning {_notes.Count} note(s)");
        return _notes.AsReadOnly();
    }
}

